// §19 WF03 — คัดรายการติดตามที่ถึงกำหนด: ต้องผ่าน ①consent ②opt-out ③โควต้าความถี่
const res = $json || {};
const items = res.followUps || res.items || res.data || [];
const queue = [], blocked = [];
for (const f of items) {
  const channel = String(f.channel || 'email').toLowerCase();
  const reasons = [];
  if (f.unsubscribed === true || f.optOut === true) reasons.push('opt-out');
  if (channel === 'email' && f.consentMarketing === false) reasons.push('ไม่ยินยอมการตลาด');
  if (Number(f.sentToday || 0) >= 1) reasons.push('ส่งแล้ววันนี้');
  if (Number(f.sentThisWeek || 0) >= 3) reasons.push('ครบโควต้าสัปดาห์');
  if (reasons.length) { blocked.push({ followUpId: f.followUpId, name: f.name, reasons }); continue; }
  queue.push({ followUpId: f.followUpId || null, prospectId: f.prospectId, name: f.name || 'ผู้สนใจ',
    channel, email: f.email || null, phone: f.phone || null, lineUserId: f.lineUserId || null,
    dayOffset: f.dayOffset ?? null, topic: f.topic || null, interests: f.interests || [],
    scheduledAt: f.scheduledAt || null, lastContactAt: f.lastContactAt || null });
}
return [{ json: { due: items.length, queue, blockedCount: blocked.length, blocked: blocked.slice(0, 10),
  window: res.window || '24h', at: new Date().toISOString() } }];

// ประกอบร่างข้อความ + payload สำหรับสร้างงานให้ตัวแทน
const draft = String(($json && $json.output) || '').trim();
const item = $('วนทีละ 5 รายการ').first().json;
const name = item.name || 'ผู้สนใจ';
const subject = 'ติดตามผลความสนใจประกัน — ' + name;
const body = draft || ('สวัสดีคุณ ' + name + '\n\nขออนุญาตติดตามความสนใจที่แจ้งไว้กับ AI Insurance Network Tree '
  + (item.topic ? ('เรื่อง ' + item.topic + ' ') : '') + '\nยินดีให้ข้อมูลเพิ่มเติมโดยไม่มีข้อผูกมัดค่ะ\n\nด้วยความนับถือ\nทีมตัวแทน AI Insurance Network Tree');
return [{ json: { followUpId: item.followUpId, prospectId: item.prospectId, name, channel: item.channel,
  email: item.email, phone: item.phone, dayOffset: item.dayOffset, topic: item.topic,
  subject, draft: body, live: String($env.PI_FOLLOWUP_LIVE || 'false') === 'true' } }];

