// ส่งกลับเข้า loop (splitInBatches จะดึงรายการถัดไปเอง) — อ่านค่าที่ต้องใช้จาก node 'ประกอบร่าง + payload งาน'
const src = $('ประกอบร่าง + payload งาน').first().json;
return [{ json: { followUpId: src.followUpId || null, prospectId: src.prospectId, name: src.name,
  ok: $json.ok !== false, sent: $json.sent === true,
  taskId: $json.taskId || null, via: $json.via || null, error: $json.error || null } }];

// สรุปผลรอบติดตาม (จากผลที่วนได้ทั้งหมด)
const rows = $('สรุปผลรายรายการ').all().map(i => i.json);
const sent = rows.filter(r => r.sent).length;
const tasks = rows.filter(r => r.taskId).length;
const failed = rows.filter(r => r.ok === false).length;
const src = $('กรอง consent + โควต้าความถี่').first().json;
return [{ json: { ok: failed === 0, due: src.due, queued: src.queue.length, sent, tasks, failed,
  blocked: src.blockedCount, at: new Date().toISOString() } }];
